/**
 * Worker entry: the OpenNext (Next.js) handler plus a daily cron (free Cron Trigger, 12:00 UTC = 09:00 Buenos Aires).
 * The cron sends ONE push per user for invoices that just became overdue (lib/documents-push.ts).
 */
// Generated by `opennextjs-cloudflare build`; it may or may not exist when `next build` type-checks this file.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { notifyOverdueInvoices } from "./lib/documents-push.ts";
import { todayBA } from "./lib/agenda-dates.ts";

type Env = { DB: Parameters<typeof notifyOverdueInvoices>[0]; VAPID_PUBLIC_KEY?: string; VAPID_PRIVATE_KEY?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };
const ADMIN_EMAIL = "lucianoolivabianco@gmail.com"; // VAPID subject; same value as lib/auth.ts (not imported: it pulls Better Auth into the cron)

async function runDailyJobs(env: Env, now = new Date()) {
  if (!env.VAPID_PUBLIC_KEY || !env.VAPID_PRIVATE_KEY) return null;
  return notifyOverdueInvoices(env.DB, todayBA(now), { publicKey: env.VAPID_PUBLIC_KEY, privateKey: env.VAPID_PRIVATE_KEY, subject: `mailto:${ADMIN_EMAIL}` });
}

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(runDailyJobs(env));
  },
};

export default worker;
